const results = [];

for (const item of $input.all()) {
  let emails = item.json;

  // Normalizza in array:
  if (!emails) {
    emails = [];
  } else if (!Array.isArray(emails)) {
    // Se è avvolto in una proprietà comune
    if (Array.isArray(emails.emails)) {
      emails = emails.emails;
    } else if (Array.isArray(emails.messages)) {
      emails = emails.messages;
    } else if (typeof emails === 'object' && (emails.id || emails.snippet || emails.From || emails.To)) {
      // singolo oggetto email -> mettilo in array
      emails = [emails];
    } else {
      // fallback: non iterabile
      emails = [];
    }
  }

  for (const email of emails) {
    results.push({
      snippet: email.snippet ?? '',
      from: email.From ?? email.from ?? '',
      to: email.To ?? email.to ?? '',
    });
  }
}

// Output unico con proprietà "data"
return [
  {
    json: {
      data: results,
    },
  },
];
